WITH filtered AS (SELECT *, COALESCE(location, 'N/A') location_filled, LOWER(dept_name) dept_name_lower FROM departments WHERE dept_name IS NOT NULL AND location IN ('London', 'Berlin', 'Bangkok')), enriched AS (SELECT id, dept_name, location, SUM(budget) OVER (PARTITION BY location, dept_name) location_sum_budget, SUM(budget) OVER (PARTITION BY dept_name ORDER BY budget ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) cumulative_budget, NTILE(3) OVER (ORDER BY budget DESC, id ASC) budget_bucket FROM filtered), scored AS (SELECT *, RANK() OVER (ORDER BY cumulative_budget DESC NULLS FIRST) cumulative_budget_rank, NTILE(5) OVER (ORDER BY budget_bucket ASC, id ASC) budget_bucket_bucket FROM enriched), eligible AS (SELECT s.* FROM scored s WHERE EXISTS (SELECT 1 FROM employees ch WHERE ch.dept_id = s.id AND NOT ch.is_remote)), with_latest AS (SELECT s.id, s.location_sum_budget, s.budget_bucket, latest.employee_job_title FROM eligible s JOIN LATERAL (SELECT c.job_title AS employee_job_title FROM employees c WHERE c.dept_id = s.id ORDER BY c.hire_date DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT employee_job_title, COUNT(*) FILTER (WHERE employee_job_title = 'Director') AS director_rows, COUNT_IF(employee_job_title = 'Engineer') AS engineer_events, SORT_ARRAY(COLLECT_SET(employee_job_title)) AS employee_job_title_list FROM with_latest GROUP BY employee_job_title ORDER BY engineer_events DESC;
